 }
}
Field guidance:
- historical_evidence and failed_approaches: only records returned by a tool, with the status as recorded; empty lists
  if nothing relevant was returned.
- testability.p_testable: probability that the question can be answered with the stated data at useful statistical power.
- prior_work.already_answered: whether retrieved earlier work already answered substantially the same question.
  Use "unknown" if no earlier work was retrieved. List identifiers you relied on in prior_work.cited.
- predicted_outcome: probabilities (summing to 1) of what a competent test of the question as posed would conclude:
  supported, rejected (adequately powered null), untestable (cannot be tested with this data), artifact (apparent
  effect produced by a flaw), uncertain (inconclusive or inadequately tested).
- decision: proceed, proceed_with_changes (state the changes in design), or do_not_proceed.
- design: a pre-registration-quality plan even if the decision is do_not_proceed (then describe the minimum viable test).

{
 "research_concepts": ["defensive suppression", "suppression-conditional recommended mix", "counter strategy (best/avoid)", "adherence to recommended play mix", "series and game winning", "team-quality confounding"],
 "methodological_questions": [
  "Is the suppression-conditional recommended mix defined from information available before each game or series, independently of the outcome?",
  "Can adherence be measured reliably from play-type tags, given the recorded tagger floor for CUT and PNR?",
  "Does a series-level test with about 54 units have enough power to detect an adherence-to-winning association after adjusting for team strength?",
  "Does the series winner label come from the official record rather than inference?"
 ],
 "historical_evidence": [
  {
   "id": "FAM:SF-APPS-017",
   "status_as_recorded": "not a hypothesis test",
   "finding": "Execution-conformance study of the observed play-type mix against the recommended opener, using 2025-26 playoff G1s (4 games x 2 offenses). Average absolute gap on leverage buckets was 4.5pp to 24.0pp. Four of eight sides best matched opener #3, not rank-1. CUT and PNR were muted by a tagger floor. The study had a single-game horizon and no outcome comparison."
  },
  {
   "id": "FAM:SF-APPA-008",
   "status_as_recorded": "artifact",
   "finding": "Audit of an overnight LLM adaptation-analysis batch that claimed 'adaptation predicts series winners 9/10'. Series winners were LLM-inferred and never looked up (0/2073 lookups). The 706 findings had n<5. One series score was invented. The claim was rated as an artifact arising from construction and labelling flaws."
  },
  {
   "id": "FAM:SF-CHT-039",
   "status_as_recorded": "untestable",
   "finding": "Series-level AVOID share vs winning. Game-level rho=-0.19, p=0.008, with inflated n and team-quality confounding. Series-level rho=-0.26, p=0.07, n=50, underpowered; the record estimates about 80 series are needed for p<0.05. Low AVOID-share bin 52.6% vs 37.0% in the 25-50% bin. The record's observed verdict is 'inconclusive'. Team quality (OKC cited as disciplined and good) confounds the result."
  },
  {
   "id": "FAM:SF-APPM-048",
   "status_as_recorded": "untestable",
   "finding": "NYK vs PHI 2025-26 series retrospective of model vs observed PPP and favourite. NYK delta -0.075 (within 0.10); PHI delta -0.205 (outside). Predicted gap in the same direction as observed. Favourite correct at NYK WP 84.0%, sweep 100%. Based on n=1 series (4 games)."
  }
 ],
 "failed_approaches": [
  {
   "id": "FAM:SF-APPS-017",
   "what_failed": "Measuring execution conformance of the observed mix against the recommended opener and treating it as a proxy for adherence.",
   "why": "Recorded as descriptive only. The tagger floor muted CUT and PNR, the horizon was a single game, there was no outcome comparison, and the failure type was recorded as E_unclear."
  },
  {
   "id": "FAM:SF-APPA-008",
   "what_failed": "Claiming adaptation predicts series winners using LLM-inferred winners and sub-sample findings.",
   "why": "Recorded as an artifact: series winners were never looked up, the rule was built on inference, sample sizes were very small (n<5 in 706 findings), and some values were invented or arithmetic errors."
  },
  {
   "id": "FAM:SF-CHT-039",
   "what_failed": "Testing a series-level AVOID-share association with winning at n=50.",
   "why": "Recorded as underpowered (p=0.07) and confounded by team quality. The game-level result was inflated by non-independent observations."
  },
  {
   "id": "FAM:SF-APPM-048",
   "what_failed": "Using a single-series retrospective to validate a model's PPP gap and favourite.",
   "why": "Recorded as n=1 series. The favourite-correct outcome on an 84% favourite is a weak test."
  }
 ],
 "evidence_establishes": [
  "Earlier work by this project tried related questions (play-mix conformance, AVOID share vs winning, adaptation vs winning) and did not produce a supported association for any of them.",
  "Series-level tests with about 50 units were recorded as underpowered (FAM:SF-CHT-039).",
  "Team-quality confounding was recorded as a problem for series-level and game-level tests (FAM:SF-CHT-039).",
  "Measured play-type adherence was recorded as unreliable for some play types because of a tagger floor (FAM:SF-APPS-017).",
  "Outcome labels that were inferred rather than looked up were recorded as producing an artifact (FAM:SF-APPA-008)."
 ],
 "evidence_does_not_establish": [
  "Whether a suppression-conditional recommended mix exists in the data as a defined, pre-game object. None of the records describes one with a fixed definition.",
  "Whether adherence predicts winning once team strength is controlled. No retrieved record tests this with adjustment.",
  "Any effect size for adherence versus winning in the 2022-23 to 2025-26 data.",
  "Whether the 54 series unit count matches the series used in the earlier families. The records cite n=50 and n=1."
 ],
 "own_inferences": [
  "The recommended mix as posed is likely to be built from the same play-by-play used to score adherence and outcomes. If so, adherence would be partly determined by the outcome (OUTCOME_DERIVED_LABEL) and could not be tested as a predictor.",
  "At about 54 series, the test would be underpowered for any plausible effect, and team quality (which drives both adherence and winning) would need to be modelled explicitly.",
  "The most defensible question may be a descriptive, team-adjusted association at game level with cluster-robust inference, not a series-level prediction claim."
 ],
 "uncertainties": [
  "The retrieval returned four records. None is a direct test of adherence to a recommended mix vs winning, so the historical picture is indirect.",
  "The records give the n=50 series analysis, the 2025-26 G1 descriptive study, and an n=1 retrospective. Whether those samples overlap with the 54-series unit is not recorded.",
  "The effect size assumed by the record's '~80 series' estimate is not stated in the record.",
  "The tagger-floor limitation on CUT and PNR is recorded for one study. Whether it applies to all seasons in scope is not recorded.",
  "No record gives a validated recommended-mix model or its training cut-off.",
  "The series-winner source for the 54 units is not stated in the task. The audit record shows that LLM-inferred winners are a known failure."
 ],
 "historical_effect": {
  "changed_decision": "yes",
  "explanation": "Before retrieval the question looked testable at series level with a defined mix. The retrieved records show that earlier series-level tests with about 50 units were underpowered and confounded by team quality, that play-mix conformance was measured only descriptively, and that LLM-inferred winners produced an artifact. This moves the decision to do_not_proceed as posed. A narrower, pre-registered test is still possible (see design)."
 },
 "testability": {
  "p_testable": 0.1,
  "blocking_constraints": [
   {"code": "SAMPLE_SIZE_POWER", "text": "About 54 series is below the roughly 80 cited in FAM:SF-CHT-039 for the related series-level test, and the effect size is unknown."},
   {"code": "MEASURE_RELIABILITY", "text": "Play-type adherence is unreliable for CUT and PNR under the recorded tagger floor (FAM:SF-APPS-017)."},
   {"code": "CONFOUNDING", "text": "Team quality drives both mix adherence and winning, and was recorded as an unresolved confound (FAM:SF-CHT-039)."}
  ]
 },
 "prior_work": {
  "already_answered": "no",
  "cited": ["FAM:SF-APPS-017", "FAM:SF-APPA-008", "FAM:SF-CHT-039", "FAM:SF-APPM-048"],
  "summary": "No retrieved record tests whether adherence to a suppression-conditional recommended mix predicts winning with team strength adjusted. The related records address conformance descriptively, AVOID share at n=50 (underpowered, confounded), an artifact-prone adaptation claim, and a single-series retrospective. None answers the posed question."
 },
 "risks": [
  {"code": "SAMPLE_SIZE_POWER", "text": "About 54 series is likely underpowered for a modest adherence effect, as recorded in FAM:SF-CHT-039."},
  {"code": "CONFOUNDING", "text": "Team quality, pace and opponent strength plausibly drive both adherence and winning. Without adjustment the estimate would be spurious."},
  {"code": "MEASURE_RELIABILITY", "text": "The tagger floor on CUT and PNR (FAM:SF-APPS-017) makes adherence measurement unreliable for those play types."},
  {"code": "OUTCOME_DERIVED_LABEL", "text": "If the recommended mix is built from the same play-by-play or outcome data, adherence is partly defined by the outcome."},
  {"code": "LEAKAGE_LOOKAHEAD", "text": "If the mix or conditioning uses in-series or post-game information, the test leaks future information into the predictor."},
  {"code": "LABEL_ERROR", "text": "Series winners must come from the official record. Inferred winners produced an artifact in FAM:SF-APPA-008."},
  {"code": "BASE_RATE", "text": "Favourites win most series. Any adherence signal must be compared with a favourite-only baseline, as the n=1 retrospective shows (FAM:SF-APPM-048)."},
  {"code": "MULTIPLE_TESTING", "text": "Multiple conditioning rules, play types and bins invite selection of the best-looking result."},
  {"code": "IMPLEMENTATION_BUG", "text": "Graph-derived possession points and series scores may contain errors (an invented score is recorded in FAM:SF-APPA-008). Reconciliation against the box score is required."},
  {"code": "PLACEBO_DEPENDENCE", "text": "Without a placebo mix or placebo window, an adherence association cannot be separated from generic team-quality effects."}
 ],
 "predicted_outcome": {
  "supported": 0.03,
  "rejected": 0.02,
  "untestable": 0.45,
  "artifact": 0.2,
  "uncertain": 0.3
 },
 "decision": "do_not_proceed",
 "design": {
  "estimand": "Minimum viable test: the team-adjusted association between pre-specified mix adherence and game winning, within series, with no series-level causal or predictive claim.",
  "unit": "Game (team-game), with series as the cluster. Series-level winning is not the primary unit.",
  "sample": "All 2022-23 to 2025-26 regular-season and playoff games with complete play-by-play. The 2025-26 playoffs are included only after completion (2026-06-21). Series winners come from the official record, not inference.",
  "power": "Power must be calculated before analysis for the chosen effect size, using cluster-robust variance. The records indicate 54 series is likely insufficient for a modest effect; if the power calculation fails, the test is reported as a descriptive exploratory result only.",
  "controls": "Pre-game team strength (e.g. prior-season rating), opponent strength, pace, home court, rest and injuries. The recommended mix is fixed from pre-game data only (no in-game or post-game information). Adherence uses play types with adequate tagging; CUT and PNR are excluded or flagged under the tagger floor.",
  "falsification": "A placebo mix (e.g. adherence to another team's mix, or a time-shifted mix) and a favourite-only baseline. The adherence association must exceed both.",
  "multiplicity": "One primary pre-registered adherence measure and one primary model. Other play types and conditioning rules are secondary and labelled exploratory.",
  "decision_rule": "Report a supported association only if the primary adherence effect is positive and significant at the pre-registered level after team-strength adjustment, exceeds the placebo and favourite-only baselines, and survives the cluster-robust check. Otherwise report inconclusive or rejected as the data show. Do not report a series-level predictive claim.",
  "data_version": "NBA stats API per-game files for 2022-23 to 2025-26 as available on 2026-06-16; 2025-26 regular season complete from 2026-04-13; 2025-26 playoffs complete from 2026-06-21, partial before. Series winners from the official record."
 }
}

